#include <algorithm>
#include <iostream>
#include <string>
using namespace std;

string s;
int dp[510][510];

int main()
{
    int n;
    cin >> n >> s;

    for (int i = 0; i < n; i++)
        dp[i][i] = 1;

    for (int l = 2; l <= n; l++) {
        for (int i = n - l; i >= 0; i--) {
            int j = i + l - 1;

            dp[i][j] = 1e9;
            for (int k = i; k < j; k++)
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j]);

            if (s[i] == s[j]) {
                dp[i][j] = min(dp[i][j], dp[i + 1][j]);
                dp[i][j] = min(dp[i][j], dp[i + 1][j - 1] + 1);
            }
        }
    }

    cout << dp[0][n - 1] << '\n';

    return 0;
}

